CREATE OR REPLACE FUNCTION public.set_employee_loan_active(_loan uuid,_active boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE l public.employee_loans; BEGIN IF NOT public.is_admin_or_manager(auth.uid()) OR NOT public.has_workspace_access(auth.uid(),'payroll') THEN RAISE EXCEPTION 'Payroll management access required'; END IF; IF _active IS NULL THEN RAISE EXCEPTION 'Choose loan status'; END IF; SELECT * INTO l FROM public.employee_loans WHERE id=_loan AND org_id=public.current_org_id() FOR UPDATE; IF l.id IS NULL THEN RAISE EXCEPTION 'Loan not found'; END IF; IF _active AND EXISTS(SELECT 1 FROM public.employee_records WHERE user_id=l.user_id AND permanently_deleted_at IS NOT NULL) THEN RAISE EXCEPTION 'Removed employee loans cannot be reactivated'; END IF; IF _active AND l.balance<=0 THEN RAISE EXCEPTION 'Loan already repaid'; END IF; UPDATE public.employee_loans SET is_active=_active WHERE id=l.id; END $$;